local AntiaddctionNoticePanel ={}function AntiaddctionNoticePanel:ctor()    --todo: 这里可以做些数据初始化工作endfunction AntiaddctionNoticePanel:OnInitialize()    AntiaddctionNoticePanel.__super.OnInitialize(self)    self:SetContent();    --todo: 在这里做些初始化工作endfunction AntiaddctionNoticePanel:RegistEvents()    AntiaddctionNoticePanel.__super.RegistEvents(self)    self:AddOnClickedEvent("Button_OK", self.OnCloseBtnClick, self);    self:AddControlEvent("ScrollBox_0", "OnUserScrolled", self.OnScrolled, self);    --todo: 在这里注册事件endfunction AntiaddctionNoticePanel:UnRegistEvents()    --todo: 在这里反注册事件    AntiaddctionNoticePanel.__super.UnRegistEvents(self)endfunction AntiaddctionNoticePanel:OnPostInitialize()    AntiaddctionNoticePanel.__super.OnPostInitialize(self)    --todo: OnPostInitialize在OnInitialize、RegistEvents之后，有需要在RegistEvents后初始化的工作写这里end-- 仅在需要监听状态变化时写这个函数--[[function UI_Template:OnModeSwitch(preStatus, currentStatus)    end]]function AntiaddctionNoticePanel:Close()    --todo: 这里做些消耗回收动作，注意UI_Template.__super.Close(self)一定要写在最后，遵循先进后出原则    AntiaddctionNoticePanel.__super.Close(self)endfunction AntiaddctionNoticePanel:SetContent()    self.UIRoot.UTRichTextBlock_TipsContent:SetText(LongTxt.AntiAddictionContent);    self.UIRoot.TextBlock_WindowsTitle:SetText(LongTxt.AntiAddictionTitle);    self.UIRoot.Button_OK:SetVisibility(UEnums.ESlateVisibility.Collapsed);    self.UIRoot.Button_OK:SetIsEnabled(true);endfunction AntiaddctionNoticePanel:OnScrolled(offset)    log("enter offset :" .. tostring(offset));    if offset >= 1308 then        self.UIRoot.Button_OK:SetVisibility(UEnums.ESlateVisibility.Visible);    endendfunction AntiaddctionNoticePanel:OnCloseBtnClick()    self:PlayAudio(require("client.slua.config.sound").click);    AntiaddctionSystem.CloseNoticePanel();endlocal class = require("class")local ui_base = require("ui.base")local CUIAntiaddctionPanel = class(ui_base, nil, AntiaddctionNoticePanel)return C